import{_ as t,a as s,o as a,a6 as d}from"./chunks/framework.CJDy2q7X.js";const c=JSON.parse('{"title":"GDPR Data Requests","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/shop/gdpr-requests/index.md","filePath":"api/rest-api/shop/gdpr-requests/index.md","lastUpdated":1786429091000}'),r={name:"api/rest-api/shop/gdpr-requests/index.md"};function i(o,e,n,h,p,l){return a(),s("div",null,e[0]||(e[0]=[d(`<h1 id="gdpr-data-requests" tabindex="-1">GDPR Data Requests <a class="header-anchor" href="#gdpr-data-requests" aria-label="Permalink to &quot;GDPR Data Requests&quot;">​</a></h1><p>GDPR data requests let a logged-in customer exercise their data-protection rights — asking the store to <strong>delete</strong> their account data or to <strong>update</strong> the personal data held about them. Every request is created, listed, viewed, revoked and deleted by the customer who owns it; a customer can only ever see and act on their own requests.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All GDPR endpoints require an authenticated <strong>customer</strong> — provide the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page for how to obtain and send them.</p><h2 id="gdpr-must-be-enabled-by-the-store" tabindex="-1">GDPR must be enabled by the store <a class="header-anchor" href="#gdpr-must-be-enabled-by-the-store" aria-label="Permalink to &quot;GDPR must be enabled by the store&quot;">​</a></h2><p>Every GDPR endpoint first checks whether GDPR data requests are switched on in the store&#39;s admin configuration. <strong>If GDPR is turned off, the call fails with HTTP 400</strong> and this message:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/errors/400&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Bad Request&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;detail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;GDPR data requests are disabled. Please enable GDPR from the admin configuration.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When you see this message, the feature has been disabled on the admin side — it must be re-enabled in the store&#39;s admin configuration before any GDPR request can be raised, listed, revoked or deleted.</p><h2 id="request-lifecycle" tabindex="-1">Request lifecycle <a class="header-anchor" href="#request-lifecycle" aria-label="Permalink to &quot;Request lifecycle&quot;">​</a></h2><p>A GDPR request moves through these statuses:</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pending</code></td><td>The request was just raised and is awaiting review.</td></tr><tr><td><code>processing</code></td><td>The store has started working on the request.</td></tr><tr><td><code>declined</code></td><td>The store reviewed and declined the request.</td></tr><tr><td><code>approved</code></td><td>The store reviewed and approved (fulfilled) the request.</td></tr><tr><td><code>revoked</code></td><td>The customer withdrew the request before it was finished.</td></tr></tbody></table><p>A customer raises a request (<code>pending</code>), can <strong>revoke</strong> it while it is still <code>pending</code> or <code>processing</code>, and can <strong>delete</strong> the request record entirely.</p><h2 id="request-type" tabindex="-1">Request type <a class="header-anchor" href="#request-type" aria-label="Permalink to &quot;Request type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>delete</code></td><td>Request the store to delete the customer&#39;s account data.</td></tr><tr><td><code>update</code></td><td>Request the store to update the personal data held about the customer.</td></tr></tbody></table><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/gdpr-requests/list-gdpr-requests.html">List own requests</a></td><td><code>GET /api/shop/gdpr-requests</code></td><td>Paginated list of the customer&#39;s own GDPR requests.</td></tr><tr><td><a href="/api/rest-api/shop/gdpr-requests/view-gdpr-request.html">View one request</a></td><td><code>GET /api/shop/gdpr-requests/{id}</code></td><td>A single request the customer owns.</td></tr><tr><td><a href="/api/rest-api/shop/gdpr-requests/create-gdpr-request.html">Raise a request</a></td><td><code>POST /api/shop/gdpr-requests</code></td><td>Raise a new <code>delete</code> or <code>update</code> request.</td></tr><tr><td><a href="/api/rest-api/shop/gdpr-requests/revoke-gdpr-request.html">Revoke a request</a></td><td><code>POST /api/shop/gdpr-requests/{id}/revoke</code></td><td>Withdraw a <code>pending</code> / <code>processing</code> request.</td></tr><tr><td><a href="/api/rest-api/shop/gdpr-requests/delete-gdpr-request.html">Delete a request</a></td><td><code>DELETE /api/shop/gdpr-requests/{id}</code></td><td>Remove a request record.</td></tr></tbody></table>`,16)]))}const q=t(r,[["render",i]]);export{c as __pageData,q as default};
